import { useEffect } from "react";
import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";
import { useProductBrandingByName } from "@/hooks/useProductBranding";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import Footer from "./components/Footer";
import Header from "./components/Header";
import IdentifierForm from "./components/IdentifierForm";
import { useLoginPasswordlessEmailCodeManager } from "./hooks/useLoginPasswordlessEmailCodeManager";

// Floating particles for B2B2C
function ConsumerParticles() {
  const particles = Array.from({ length: 12 }, (_, i) => ({
    id: i,
    left: `${Math.random() * 100}%`,
    delay: `${Math.random() * 6}s`,
    duration: `${10 + Math.random() * 8}s`,
    size: `${5 + Math.random() * 8}px`,
    opacity: 0.08 + Math.random() * 0.12,
  }));

  return (
    <div className="acul-consumer-particles">
      {particles.map((particle) => (
        <div
          key={particle.id}
          className="acul-consumer-particle"
          style={{
            left: particle.left,
            animationDelay: particle.delay,
            animationDuration: particle.duration,
            width: particle.size,
            height: particle.size,
            opacity: particle.opacity,
          }}
        />
      ))}
    </div>
  );
}

// Magic link badge
function MagicLinkBadge() {
  return (
    <div className="acul-rewards-badge">
      <span className="acul-rewards-icon">✨</span>
      <span>Passwordless Login</span>
    </div>
  );
}

// Helper to detect B2B2C product
function isB2B2CProduct(product: string | undefined): boolean {
  if (!product) return false;
  return ["acme-rewards", "beta-rewards", "gamma-rewards"].includes(product);
}

function LoginPasswordlessEmailCodeScreen() {
  const { loginPasswordlessEmailCode, texts, locales } =
    useLoginPasswordlessEmailCodeManager();

  // Get product from SDK or URL params
  const devProduct =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("ext-product")
      : null;

  const sdkProduct = (loginPasswordlessEmailCode as { screen?: { untrustedData?: { authorizationParams?: { 'ext-product'?: string } } } })
    ?.screen?.untrustedData?.authorizationParams?.['ext-product'];

  const activeProduct = sdkProduct || devProduct || undefined;
  const productBranding = useProductBrandingByName(activeProduct);
  const isB2B2C = isB2B2CProduct(activeProduct);

  // Apply theme classes
  useEffect(() => {
    document.body.classList.remove("acul-b2b-theme", "acul-b2b2c-theme");
    if (isB2B2C) {
      document.body.classList.add("acul-b2b2c-theme");
    }
    return () => {
      document.body.classList.remove("acul-b2b2c-theme");
    };
  }, [isB2B2C]);

  applyAuth0Theme(loginPasswordlessEmailCode, productBranding);
  document.title = texts?.pageTitle || locales.page.title;

  return (
    <ULThemePageLayout className="theme-universal">
      {isB2B2C && <ConsumerParticles />}

      <ULThemeCard
        className={`w-full max-w-[400px] gap-0 ${isB2B2C ? "acul-b2b2c-card" : ""}`}
      >
        {isB2B2C && (
          <div className="flex justify-center pt-4">
            <MagicLinkBadge />
          </div>
        )}

        <Header />
        <IdentifierForm />
        <Footer />

        {isB2B2C && (
          <div className="acul-b2b2c-footer">
            <p>We'll send a secure code to your email</p>
          </div>
        )}
      </ULThemeCard>
    </ULThemePageLayout>
  );
}

export default LoginPasswordlessEmailCodeScreen;
